public static boolean isBoomerang(int[][] points) {
    int n = points.length;
    if (n != 3) {
        return false;
    }

    int[] p1 = points[0], p2 = points[1], p3 = points[2];

    // Check if the angle between p1-p2 and p1-p3 is 180 degrees
    if (Math.abs(angle(p2, p3, p1)) != 180) {
        return false;
    }

    // Check if the triangle is oriented counterclockwise
    if (orientation(p1, p2, p3) >= 0) {
        return false;
    }

    return true;
}

private static double angle(int[] p1, int[] p2, int[] p3) {
    return Math.toDegrees(Math.atan2(p2[1] - p1[1], p2[0] - p1[0]) - Math.atan2(p3[1] - p1[1], p3[0] - p1[0]));
}

private static double orientation(int[] p1, int[] p2, int[] p3) {
    double value = (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p2[1] - p1[1]) * (p3[0] - p1[0]);
    return value >= 0 ? value : -value;
}
