public static int findNthUglyNumber(int n) {
    int[] dp = new int[n + 1];
    dp[1] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    for (int i = 2; i <= n; i++) {
        int x2 = dp[i2] * 2, x3 = dp[i3] * 3, x5 = dp[i5] * 5;
        dp[i] = Math.min(x2, Math.min(x3, x5));
        if (dp[i] == x2) i2++;
        if (dp[i] == x3) i3++;
        if (dp[i] == x5) i5++;
    }
    return dp[n];
}
